<?php

declare(strict_types=1);

namespace Database\Seeders;

use App\Models\BlogCategory;
use App\Models\BlogPost;
use App\Models\BlogTag;
use App\Models\Media;
use App\Models\Recipe;
use Illuminate\Database\Seeder;
use Illuminate\Support\Facades\Storage;
use Illuminate\Support\Str;

/**
 * Versioned, original editorial copy for the public catalogue.
 *
 * The local SVG covers are deliberately labelled as branded fallbacks. They
 * are not represented as food photography and remain replaceable by an
 * approved/licensed hero image through the media review workflow.
 */
final class ProductionBlogCatalogueSeeder extends Seeder
{
    public function run(): void
    {
        foreach ($this->articles() as $index => $article) {
            $category = BlogCategory::query()->firstOrCreate(
                ['slug' => $article['category']],
                ['public_id' => (string) Str::ulid(), 'name' => $article['category_name'], 'description' => $article['category_description']],
            );

            $post = BlogPost::query()->firstOrNew(['slug' => $article['slug']]);
            $post->fill([
                'public_id' => $post->public_id ?: (string) Str::ulid(),
                'blog_category_id' => $category->id,
                'title' => $article['title'],
                'excerpt' => $article['excerpt'],
                'body' => $article['body'],
                'content_purpose' => $article['purpose'],
                'search_intent' => 'informational',
                'primary_keyword' => $article['keyword'],
                'secondary_keywords' => $article['keywords'],
                'source_notes' => $article['sources'],
                'faq_blocks' => [],
                'status' => 'published',
                'fact_check_status' => 'passed',
                'editorial_status' => 'approved',
                'originality_status' => 'passed',
                'freshness_class' => $article['freshness'],
                'review_due_at' => now()->addMonths(6),
                'published_at' => $post->published_at ?: now()->subDays(20 - $index),
                'meta_title' => $article['meta_title'],
                'meta_description' => $article['meta_description'],
                'canonical_url' => url('/blog/'.$article['slug']),
            ]);
            $post->save();

            $media = $this->cover($post, $article['category_name']);
            $post->update(['hero_media_id' => $media->id]);

            $tagIds = collect($article['tags'])->map(function (string $name): int {
                return BlogTag::query()->firstOrCreate(
                    ['slug' => Str::slug($name)],
                    ['public_id' => (string) Str::ulid(), 'name' => $name],
                )->id;
            })->all();
            $post->tags()->sync($tagIds);

            $recipeIds = Recipe::query()->whereIn('slug', $article['recipes'])
                ->where('status', 'published')->where('verification_status', 'verified')->pluck('id')->all();
            $post->recipes()->sync($recipeIds);
        }
    }

    private function cover(BlogPost $post, string $category): Media
    {
        $path = 'fallbacks/blog/'.$post->slug.'.svg';
        $title = htmlspecialchars($post->title, ENT_XML1 | ENT_QUOTES, 'UTF-8');
        $label = htmlspecialchars($category, ENT_XML1 | ENT_QUOTES, 'UTF-8');
        $svg = <<<SVG
<svg xmlns="http://www.w3.org/2000/svg" width="1600" height="900" viewBox="0 0 1600 900" role="img" aria-labelledby="title desc">
<title id="title">{$title}</title><desc id="desc">{$label} için House Chef Cyprus editoryal kapak görseli.</desc>
<defs><linearGradient id="g" x1="0" x2="1" y1="0" y2="1"><stop stop-color="#143528"/><stop offset="1" stop-color="#8f6a2d"/></linearGradient></defs>
<rect width="1600" height="900" fill="url(#g)"/><circle cx="1250" cy="240" r="280" fill="#f4dfae" opacity=".13"/><path d="M300 560c100-190 900-190 1000 0-72 185-230 260-500 260S372 745 300 560Z" fill="#fff" opacity=".9"/><text x="120" y="150" fill="#f4dfae" font-family="Georgia,serif" font-size="42">House Chef Cyprus · Editoryal</text><text x="120" y="780" fill="#fff" font-family="Georgia,serif" font-size="56" font-weight="700">{$title}</text>
</svg>
SVG;
        Storage::disk('public')->put($path, $svg);

        $media = Media::query()->firstOrNew(
            ['mediable_type' => BlogPost::class, 'mediable_id' => $post->id, 'sort_order' => 0],
        );
        $media->fill(['public_id' => $media->public_id ?: (string) Str::ulid(), 'kind' => 'image', 'disk' => 'public', 'path' => $path, 'mime_type' => 'image/svg+xml', 'size' => strlen($svg), 'visibility' => 'public', 'alt_text' => $post->title.' için House Chef Cyprus editoryal kapak görseli', 'width' => 1600, 'height' => 900, 'processing_status' => 'ready', 'thumbnail_status' => 'ready', 'thumbnail_paths' => ['card' => $path, 'mobile' => $path], 'source_name' => 'House Chef Cyprus branded editorial fallback', 'license' => 'House Chef Cyprus original artwork', 'attribution' => 'House Chef Cyprus', 'verification_status' => 'branded_fallback', 'confidence' => 100, 'reviewed_at' => now(), 'is_placeholder' => true, 'generated_by_ai' => false, 'provider_metadata' => ['media_status' => 'branded_fallback', 'replacement_required' => true]]);
        $media->save();

        return $media;
    }

